  standalone: true,
  imports: [DiagramCanvasComponent],
  templateUrl: './node-resizer.component.html',
})
export class NodeResizerComponent implements AfterViewInit {
  nodes = [
    { id: 'a', position: { x: 200, y: 140 }, size: { width: 220, height: 110 },
      data: { label: 'Select me, then drag a corner' },
      metadata: { sizing: { minWidth: 120, minHeight: 70, maxWidth: 460, maxHeight: 240 } } },
  ];
  edges = [];
  ngAfterViewInit() { markReady(); }
}

edges/editable-edge.text:
import { AfterViewInit, Component, viewChild } from '@angular/core';
import { DiagramCanvasComponent } from '@grafloria/angular';
import { markReady } from '../demo-ready';

/** Click the wire to select it, click its body to drop a waypoint, drag the
 *  waypoint — the route bends to follow. Every bend is undoable. */
@Component({
  standalone: true,
  imports: [DiagramCanvasComponent],
  templateUrl: './editable-edge.component.html',
})
export class EditableEdgeComponent implements AfterViewInit {
  canvas = viewChild.required(DiagramCanvasComponent);
  nodes = [
    { id: 'a', position: { x: 120, y: 180 }, size: { width: 150, height: 70 }, data: { label: 'A' } },
    { id: 'b', position: { x: 620, y: 180 }, size: { width: 150, height: 70 }, data: { label: 'B' } },
  ];
  edges = [{ id: 'e1', source: 'a', target: 'b' }];
  ngAfterViewInit() {
    // Waypoint editing is opt-in: without it a click on the wire drops nothing.
    this.canvas().activeEngine()?.setInteractionConfig({ enableWaypointEditing: true, showWaypointHandles: true });
    markReady();
  }
}

