  host = viewChild.required<ElementRef<HTMLElement>>('host');
  nodes: unknown[] = [];
  edges: unknown[] = [];

  private ink(id: string, y: number) {
    return new StrokeModel(
      [{ x: 100, y }, { x: 300, y }, { x: 500, y }],
      { color: '#1f2933', width: 4 },
      { id },
    );
