`;

@Component({
  standalone: true,
  imports: [GrafloriaDiagramComponent],
  templateUrl: './ai-style-diagram.component.html',
  styles: [HOST_CSS],
})
export class AiStyleDiagramComponent {
  readonly sources = SOURCES;
  readonly spec = { nodes: [], edges: [] };
  readonly options = { zoom: 1 };
  readonly source = signal<Source>('native');
  private readonly canvas = viewChild.required<ElementRef<HTMLDivElement>>('canvas');
  private readonly src = viewChild<ElementRef<HTMLPreElement>>('src');
  private api?: DiagramInstance;

  constructor() {
    // The source under the canvas: its text, coloured as what it is — Mermaid,
    // or the JavaScript spec. The <pre> renders empty; the colouring fills it.
    effect(() => {
      const which = this.source();
      const pre = this.src()?.nativeElement;
      if (!pre) return;
      pre.textContent = which === 'mermaid' ? MERMAID_TEXT : NATIVE_TEXT;
      void highlightBlock(pre, which === 'mermaid' ? 'mermaid' : 'javascript');
    });
  }

  onReady(instance: DiagramInstance) {
    this.api = instance;
    // A diagram to read: ports appear only while a line is being drawn.
    instance.getEngine().setInteractionConfig({ portVisibility: 'hidden' as never });
    draw(instance, 'native');
    // 1:1, the 960 × 480 drawing centred in the canvas — the scale it was drawn at.
    const r = this.canvas().nativeElement.getBoundingClientRect();
    instance.viewport.setZoom(1);
    instance.viewport.setViewport({ x: -Math.max(0, (r.width - 960) / 2), y: -Math.max(0, (r.height - 480) / 2), width: r.width, height: r.height });
    instance.renderNow();
    markReady();
  }

  show(which: Source) {
    if (this.api) draw(this.api, which);
    this.source.set(which);
  }
}

